#include <stdio.h>
#include <string.h>

int main(void) {
    char numero[1005];
    char palavra[1005];
    int mapa[26] = {0};

    const char *grupos[] = {
        "abc", "def", "ghi", "jkl",
        "mno", "pqrs", "tuv", "wxyz"
    };

    for (int i = 0; i < 8; i++) {
        for (const char *p = grupos[i]; *p; p++) {
            mapa[*p - 'a'] = i + 2;
        }
    }

    scanf("%1000s", numero);

    int m;
    scanf("%d", &m);

    int resposta = 0;
    size_t tamanho = strlen(numero);

    for (int i = 0; i < m; i++) {
        scanf("%1000s", palavra);

        if (strlen(palavra) != tamanho) {
            continue;
        }

        int corresponde = 1;
        for (size_t j = 0; j < tamanho; j++) {
            if (mapa[palavra[j] - 'a'] != numero[j] - '0') {
                corresponde = 0;
                break;
            }
        }

        resposta += corresponde;
    }

    printf("%d\n", resposta);
    return 0;
}
